"""Curve-driven pencil geometry and capped cutting volumes generated by nodes."""
import bpy
from mathutils import Vector
from .node_primitives import Graph,set_input,material_uv,sync_materials

GENERATOR='wavelength.geometry_nodes.pencil'

def shape_group(kind):
    name=f'wavelength · Pencil {kind.title()} · v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=Graph(name,GENERATOR,[('Geometry','NodeSocketGeometry',None),('Guide','NodeSocketObject',None),('Height','NodeSocketFloat',1.),('Direction','NodeSocketVector',(0,0,1)),('Flatten','NodeSocketVector',(0,0,0)),('Restore','NodeSocketVector',(0,0,0)),('Origin','NodeSocketVector',(0,0,0)),('Normal','NodeSocketVector',(0,0,1)),('Closed','NodeSocketBool',True),('Material','NodeSocketMaterial',None),('Units','NodeSocketFloat',1.),('Texture Width','NodeSocketFloat',64.),('Texture Height','NodeSocketFloat',64.)])
    q=g.input.outputs;info=g.node('GeometryNodeObjectInfo','Editable native curve');info.transform_space='ORIGINAL';g.wire(q['Guide'],info.inputs['Object'])
    curve=info.outputs['Geometry']
    handles=g.node('GeometryNodeInputCurveHandlePositions','Curved control handles');handles.inputs['Relative'].default_value=True
    lengths=[]
    for socket in handles.outputs:
        length=g.node('ShaderNodeVectorMath','Handle length');length.operation='LENGTH';g.wire(socket,length.inputs[0]);lengths.append(length.outputs['Value'])
    stats=g.node('GeometryNodeAttributeStatistic','Preserve curved segments');stats.data_type='FLOAT';stats.domain='POINT';g.wire(curve,stats.inputs['Geometry']);g.wire(g.math('MAXIMUM',*lengths),stats.inputs['Attribute'])
    poly=g.node('GeometryNodeCurveSplineType','Straight control polygon');poly.spline_type='POLY';g.wire(curve,poly.inputs['Curve'])
    curve=g.choose(g.math('GREATER_THAN',stats.outputs['Max'],1e-7),curve,poly.outputs['Curve'],'GEOMETRY')
    edges=g.node('GeometryNodeCurveToMesh','Sample native curve');g.wire(curve,edges.inputs['Curve'])
    if kind=='EDGES':return g.finish(edges.outputs['Mesh'])
    flat=g.transform(curve,rotation=q['Flatten'])
    fill=g.node('GeometryNodeFillCurve','Fill closed outline')
    if hasattr(fill,'mode'):fill.mode='NGONS'
    else:fill.inputs['Mode'].default_value='N-gons'
    g.wire(flat,fill.inputs['Curve']);face=fill.outputs['Mesh']
    if kind=='FACE':return g.finish(material_uv(g,g.transform(face,translation=q['Origin'],rotation=q['Restore'])))
    scale=g.node('ShaderNodeVectorMath','Signed extrusion height');scale.operation='SCALE';g.wire(q['Direction'],scale.inputs[0]);g.wire(q['Height'],scale.inputs['Scale'])
    extrude=g.node('GeometryNodeExtrudeMesh','Closed volume extrusion');extrude.mode='FACES';extrude.inputs['Individual'].default_value=False
    g.wire(face,extrude.inputs['Mesh']);g.wire(q['Height'],extrude.inputs['Offset Scale'])
    rotate=g.node('ShaderNodeVectorRotate','Local extrusion direction');rotate.rotation_type='EULER_XYZ';g.wire(q['Direction'],rotate.inputs['Vector']);g.wire(q['Flatten'],rotate.inputs['Rotation'])
    delta=g.node('ShaderNodeVectorMath','Directional correction');delta.operation='SUBTRACT';g.wire(rotate.outputs[0],delta.inputs[0]);delta.inputs[1].default_value=(0,0,1)
    stretch=g.node('ShaderNodeVectorMath','Directional height');stretch.operation='SCALE';g.wire(delta.outputs[0],stretch.inputs[0]);g.wire(q['Height'],stretch.inputs['Scale'])
    top=g.node('GeometryNodeSetPosition','Move extruded cap');g.wire(extrude.outputs['Mesh'],top.inputs['Geometry']);g.wire(extrude.outputs['Top'],top.inputs['Selection']);g.wire(stretch.outputs[0],top.inputs['Offset'])
    # Face-region extrusion replaces the original face. Add its reversed cap.
    flip=g.node('GeometryNodeFlipFaces','Bottom cap');g.wire(face,flip.inputs['Mesh'])
    join=g.node('GeometryNodeJoinGeometry','Capped volume');g.wire(top.outputs['Geometry'],join.inputs['Geometry']);g.wire(flip.outputs['Mesh'],join.inputs['Geometry'])
    merge=g.node('GeometryNodeMergeByDistance','Weld cap boundary');g.wire(join.outputs[0],merge.inputs['Geometry']);merge.inputs['Distance'].default_value=1e-6
    strip=g.node('GeometryNodeExtrudeMesh','Open path surface extrusion');strip.mode='EDGES';g.wire(edges.outputs['Mesh'],strip.inputs['Mesh']);g.wire(scale.outputs[0],strip.inputs['Offset']);strip.inputs['Offset Scale'].default_value=0
    winding=g.node('GeometryNodeFlipFaces','Outward winding for signed extrusion');g.wire(merge.outputs[0],winding.inputs['Mesh'])
    dot=g.node('ShaderNodeVectorMath','Extrusion orientation');dot.operation='DOT_PRODUCT';g.wire(q['Direction'],dot.inputs[0]);g.wire(q['Normal'],dot.inputs[1])
    g.wire(g.math('LESS_THAN',g.math('MULTIPLY',q['Height'],dot.outputs['Value']),0),winding.inputs['Selection'])
    closed=g.transform(winding.outputs[0],translation=q['Origin'],rotation=q['Restore'])
    return g.finish(material_uv(g,g.choose(q['Closed'],closed,strip.outputs['Mesh'],'GEOMETRY')))

def bake(obj):
    """Commit evaluated node geometry without constructing vertices in Python."""
    bpy.context.view_layer.update();depsgraph=bpy.context.evaluated_depsgraph_get()
    mesh=bpy.data.meshes.new_from_object(obj.evaluated_get(depsgraph),preserve_all_data_layers=True,depsgraph=depsgraph)
    if not mesh.vertices:
        bpy.data.meshes.remove(mesh);raise ValueError('The node graph produced no geometry')
    previous=obj.data;obj.data=mesh
    if previous.users==0:bpy.data.meshes.remove(previous)
    return mesh

def create(context,guide,kind,height,normal,direction):
    """Keep the source curve editable; node inputs define the generated output."""
    from . import profiles
    data=bpy.data.meshes.new('Pencil generated mesh');obj=bpy.data.objects.new('Cut Shape' if guide.data.splines[0].use_cyclic_u else 'Path Geometry',data)
    context.collection.objects.link(obj);obj.parent=guide;obj.matrix_parent_inverse.identity();obj.matrix_basis.identity()
    try:
        modifier=obj.modifiers.new('wavelength · Curve Generator','NODES');modifier.node_group=shape_group(kind);modifier.show_in_editmode=False
        set_input(modifier,'Guide',guide)
        obj['wl_source_guide']=guide;obj['wl_pencil_geometry']=kind;obj['wl_procedural_state']='PROCEDURAL'
        obj['wl_owner_profile']=context.scene.wavelength.engine;obj['wl_unit_meters']=profiles.unit_meters(context.scene.wavelength)
        set_input(modifier,'Units',obj['wl_unit_meters'])
        if kind=='EXTRUDE':guide.wavelength_cutter.height=height/obj['wl_unit_meters']
        update(obj,force=True)
        sync_materials(obj)
        # A mesh snapshot supports inspection; the graph remains authoritative.
        bake(obj)
        return obj
    except Exception:
        mesh=obj.data;bpy.data.objects.remove(obj,do_unlink=True)
        if mesh.users==0:bpy.data.meshes.remove(mesh)
        raise

def update(obj,force=False):
    guide=obj.get('wl_source_guide')
    if not guide or guide.name not in bpy.data.objects:return
    settings=guide.wavelength_cutter
    closed=bool(guide.data.splines and guide.data.splines[0].use_cyclic_u)
    normal=Vector(guide.get('wl_cutter_normal',(0,0,1))).normalized()
    up=normal if settings.direction=='NORMAL' else guide.matrix_world.to_3x3().inverted()@Vector(tuple(float(axis==settings.direction) for axis in 'XYZ'))
    spline=guide.data.splines[0]
    first=spline.bezier_points[0].co if spline.type=='BEZIER' else spline.points[0].co.to_3d()
    origin=normal*first.dot(normal)
    signature=(settings.height,settings.direction,closed,tuple(normal),tuple(up),tuple(origin))
    if not force and _state.get(obj.as_pointer())==signature:return
    rotation=normal.to_track_quat('Z','Y')
    for modifier in obj.modifiers:
        if modifier.type=='NODES' and modifier.node_group and modifier.node_group.get('wl_generator')==GENERATOR:
            for name,value in [('Origin',origin),('Normal',normal),('Height',settings.height*obj.get('wl_unit_meters',1)),('Direction',up),('Closed',closed),('Flatten',rotation.inverted().to_euler()),('Restore',rotation.to_euler())]:set_input(modifier,name,value)
    obj.update_tag();_state[obj.as_pointer()]=signature

_state={}
def tick():
    for obj in tuple(bpy.data.objects):
        if obj.get('wl_pencil_geometry') and obj.get('wl_procedural_state')=='PROCEDURAL':
            try:update(obj)
            except (ReferenceError,RuntimeError,ValueError):pass
    return .1

def finalize(obj):
    update(obj,force=True);bake(obj)
    for modifier in list(obj.modifiers):
        if modifier.type=='NODES' and modifier.node_group and modifier.node_group.get('wl_generator')==GENERATOR:obj.modifiers.remove(modifier)
    matrix=obj.matrix_world.copy();obj.parent=None;obj.matrix_world=matrix
    obj['wl_procedural_state']='FINALIZED';_state.pop(obj.as_pointer(),None)

def volume(context,points,normal,low,high):
    """An input polygon is a curve; Fill/Extrude nodes create the cutter mesh."""
    matrix=normal.to_track_quat('Z','Y').to_matrix().to_4x4();matrix.translation=points[0]
    inverse=matrix.inverted()
    data=bpy.data.curves.new('.Cutter Input','CURVE');data.dimensions='3D';spline=data.splines.new('POLY');spline.points.add(len(points)-1)
    for point,value in zip(spline.points,points):
        local=inverse@value;point.co=(local.x,local.y,0,1)
    spline.use_cyclic_u=True
    guide=bpy.data.objects.new('.Cutter Input',data);context.collection.objects.link(guide);guide.matrix_world=matrix
    output=None
    try:
        output=create(context,guide,'EXTRUDE',high-low,normal,normal)
        # create() interprets the stored local plane normal, which is XY here.
        guide['wl_cutter_normal']=(0,0,1);guide.wavelength_cutter.direction='NORMAL'
        update(output,force=True);finalize(output)
        matrix=output.matrix_world.copy();matrix.translation+=normal*low;output.matrix_world=matrix
        return output
    except Exception:
        if output:
            mesh=output.data;bpy.data.objects.remove(output,do_unlink=True)
            if mesh.users==0:bpy.data.meshes.remove(mesh)
        raise
    finally:bpy.data.objects.remove(guide,do_unlink=True);bpy.data.curves.remove(data)

def boolean(obj,cutter,operation):
    """Use the node Boolean kernel; Python still validates and commits outputs."""
    name=f'wavelength · Solid {operation.title()} · v1'
    tree=bpy.data.node_groups.get(name)
    if not tree:
        g=Graph(name,GENERATOR,[('Geometry','NodeSocketGeometry',None),('Cutter','NodeSocketObject',None)])
        info=g.node('GeometryNodeObjectInfo','World-space cutting volume');info.transform_space='RELATIVE';g.wire(g.input.outputs['Cutter'],info.inputs['Object'])
        node=g.node('GeometryNodeMeshBoolean','Exact capped solid operation');node.operation=operation;node.solver='EXACT'
        g.wire(g.input.outputs['Geometry'],node.inputs.get('Mesh 1') or node.inputs['Mesh 2']);g.wire(info.outputs['Geometry'],node.inputs['Mesh 2']);tree=g.finish(node.outputs['Mesh'])
    modifier=obj.modifiers.new('wavelength · Solid Cut','NODES');modifier.node_group=tree;set_input(modifier,'Cutter',cutter)
    return modifier
